1	/****************************************************************************
2	 * Contest 2026 team 026 - OV2640 Camera Real-time Display
3	 *
4	 * Captures frames from OV2640 camera via V4L2 interface and displays
5	 * them on the ST7789 LCD in real-time.
6	 ****************************************************************************/
7	
8	#include <nuttx/config.h>
9	#include <stdio.h>
10	#include <stdlib.h>
11	#include <string.h>
12	#include <fcntl.h>
13	#include <unistd.h>
14	#include <errno.h>
15	#include <sys/ioctl.h>
16	#include <sys/time.h>
17	#include <sys/mman.h>
18	
19	#include <nuttx/video/video.h>
20	#include <nuttx/video/fb.h>
21	
22	/****************************************************************************
23	 * Pre-processor Definitions
24	 ****************************************************************************/
25	
26	#define CAMERA_DEV_PATH   "/dev/video"
27	#define FB_DEV_PATH       "/dev/fb0"
28	#define FRAME_WIDTH       320
29	#define FRAME_HEIGHT      240
30	#define FRAME_SIZE        (FRAME_WIDTH * FRAME_HEIGHT * 2)  /* RGB565 */
31	#define LCD_WIDTH         240
32	#define LCD_HEIGHT        240
33	#define CROP_X            ((FRAME_WIDTH - LCD_WIDTH) / 2)   /* 40 */
34	#define BUF_COUNT         3
35	
36	/****************************************************************************
37	 * Private Functions
38	 ****************************************************************************/
39	
40	/****************************************************************************
41	 * Name: display_frame
42	 *
43	 * Description:
44	 *   Display a 320x240 RGB565 frame on the 240x240 LCD by center cropping.
45	 ****************************************************************************/
46	
47	static int display_frame(int fb_fd, const uint8_t *frame,
48	                         struct fb_videoinfo_s *vinfo,
49	                         struct fb_planeinfo_s *pinfo)
50	{
51	  uint8_t *fbmem = (uint8_t *)pinfo->fbmem;
52	  int y;
53	
54	  if (fbmem == NULL)
55	    {
56	      return -ENOMEM;
57	    }
58	
59	  /* Center crop: take middle 240 columns from 320-wide frame */
60	
61	  for (y = 0; y < LCD_HEIGHT; y++)
62	    {
63	      const uint16_t *src = (const uint16_t *)(frame +
64	                              (y * FRAME_WIDTH + CROP_X) * 2);
65	      uint16_t *dst = (uint16_t *)(fbmem + y * pinfo->stride);
66	      memcpy(dst, src, LCD_WIDTH * 2);
67	    }
68	
69	  return OK;
70	}
71	
72	/****************************************************************************
73	 * Public Functions
74	 ****************************************************************************/
75	
76	int main(int argc, char *argv[])
77	{
78	  int cam_fd;
79	  int fb_fd;
80	  int ret;
81	  struct v4l2_format fmt;
82	  struct v4l2_requestbuffers req;
83	  struct v4l2_buffer buf;
84	  enum v4l2_buf_type type;
85	  struct fb_videoinfo_s vinfo;
86	  struct fb_planeinfo_s pinfo;
87	  struct timeval start_tv;
88	  struct timeval now_tv;
89	  int frame_count = 0;
90	  uint8_t *frame_data;
91	
92	  printf("OV2640 Camera -> LCD Real-time Display\n");
93	
94	  /* Open framebuffer device */
95	
96	  fb_fd = open(FB_DEV_PATH, O_RDWR);
97	  if (fb_fd < 0)
98	    {
99	      printf("ERROR: Failed to open %s: %d\n", FB_DEV_PATH, errno);
100	      return -errno;
101	    }
102	
103	  /* Get framebuffer info */
104	
105	  ret = ioctl(fb_fd, FBIOGET_VIDEOINFO, (unsigned long)&vinfo);
106	  if (ret < 0)
107	    {
108	      printf("ERROR: FBIOGET_VIDEOINFO failed: %d\n", errno);
109	      close(fb_fd);
110	      return ret;
111	    }
112	
113	  ret = ioctl(fb_fd, FBIOGET_PLANEINFO, (unsigned long)&pinfo);
114	  if (ret < 0)
115	    {
116	      printf("ERROR: FBIOGET_PLANEINFO failed: %d\n", errno);
117	      close(fb_fd);
118	      return ret;
119	    }
120	
121	  printf("LCD: %dx%d, stride=%d\n", vinfo.xres, vinfo.yres, pinfo.stride);
122	
123	  /* Open camera device */
124	
125	  cam_fd = open(CAMERA_DEV_PATH, O_RDONLY);
126	  if (cam_fd < 0)
127	    {
128	      printf("ERROR: Failed to open %s: %d\n", CAMERA_DEV_PATH, errno);
129	      close(fb_fd);
130	      return -errno;
131	    }
132	
133	  /* Set camera format: QVGA RGB565 */
134	
135	  memset(&fmt, 0, sizeof(fmt));
136	  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
137	  fmt.fmt.pix.width = FRAME_WIDTH;
138	  fmt.fmt.pix.height = FRAME_HEIGHT;
139	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
140	
141	  ret = ioctl(cam_fd, VIDIOC_S_FMT, (unsigned long)&fmt);
142	  if (ret < 0)
143	    {
144	      printf("ERROR: VIDIOC_S_FMT failed: %d\n", errno);
145	      goto err_close;
146	    }
147	
148	  /* Request buffers */
149	
150	  memset(&req, 0, sizeof(req));
151	  req.count = BUF_COUNT;
152	  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
153	  req.memory = V4L2_MEMORY_MMAP;
154	
155	  ret = ioctl(cam_fd, VIDIOC_REQBUFS, (unsigned long)&req);
156	  if (ret < 0)
157	    {
158	      printf("ERROR: VIDIOC_REQBUFS failed: %d\n", errno);
159	      goto err_close;
160	    }
161	
162	  /* Queue all buffers */
163	
164	  for (int i = 0; i < BUF_COUNT; i++)
165	    {
166	      memset(&buf, 0, sizeof(buf));
167	      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
168	      buf.memory = V4L2_MEMORY_MMAP;
169	      buf.index = i;
170	
171	      ret = ioctl(cam_fd, VIDIOC_QBUF, (unsigned long)&buf);
172	      if (ret < 0)
173	        {
174	          printf("ERROR: VIDIOC_QBUF[%d] failed: %d\n", i, errno);
175	          goto err_close;
176	        }
177	    }
178	
179	  /* Start streaming */
180	
181	  type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
182	  ret = ioctl(cam_fd, VIDIOC_STREAMON, (unsigned long)&type);
183	  if (ret < 0)
184	    {
185	      printf("ERROR: VIDIOC_STREAMON failed: %d\n", errno);
186	      goto err_close;
187	    }
188	
189	  printf("Camera streaming started. Press Ctrl+C to stop.\n");
190	  gettimeofday(&start_tv, NULL);
191	
192	  /* Main capture loop */
193	
194	  while (1)
195	    {
196	      /* Dequeue a frame */
197	
198	      memset(&buf, 0, sizeof(buf));
199	      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
200	      buf.memory = V4L2_MEMORY_MMAP;
201	
202	      ret = ioctl(cam_fd, VIDIOC_DQBUF, (unsigned long)&buf);
203	      if (ret < 0)
204	        {
205	          printf("ERROR: VIDIOC_DQBUF failed: %d\n", errno);
206	          break;
207	        }
208	
209	      /* Map frame data */
210	
211	      frame_data = (uint8_t *)mmap(NULL, buf.length, PROT_READ,
212	                                    MAP_SHARED, cam_fd, buf.m.offset);
213	      if (frame_data == MAP_FAILED)
214	        {
215	          printf("ERROR: mmap failed: %d\n", errno);
216	          break;
217	        }
218	
219	      /* Display frame on LCD */
220	
221	      display_frame(fb_fd, frame_data, &vinfo, &pinfo);
222	
223	      /* Unmap */
224	
225	      munmap(frame_data, buf.length);
226	
227	      /* Requeue buffer */
228	
229	      ret = ioctl(cam_fd, VIDIOC_QBUF, (unsigned long)&buf);
230	      if (ret < 0)
231	        {
232	          printf("ERROR: VIDIOC_QBUF failed: %d\n", errno);
233	          break;
234	        }
235	
236	      /* Print FPS every second */
237	
238	      frame_count++;
239	      gettimeofday(&now_tv, NULL);
240	      long elapsed_ms = (now_tv.tv_sec - start_tv.tv_sec) * 1000 +
241	                        (now_tv.tv_usec - start_tv.tv_usec) / 1000;
242	
243	      if (elapsed_ms >= 1000)
244	        {
245	          printf("FPS: %ld\n", frame_count * 1000 / elapsed_ms);
246	          frame_count = 0;
247	          start_tv = now_tv;
248	        }
249	    }
250	
251	  /* Cleanup */
252	
253	  ioctl(cam_fd, VIDIOC_STREAMOFF, (unsigned long)&type);
254	
255	err_close:
256	  close(cam_fd);
257	  close(fb_fd);
258	  return 0;
259	}
