254	/****************************************************************************
255	 * Name: gpint_attach
256	 ****************************************************************************/
257	
258	static int gpint_attach(struct gpio_dev_s *dev,
259	                        pin_interrupt_t callback)
260	{
261	  struct esp32s3gpint_dev_s *esp32s3gpint =
262	    (struct esp32s3gpint_dev_s *)dev;
263	  int irq = ESP32S3_PIN2IRQ(g_gpiointinputs[esp32s3gpint->esp32s3gpio.id]);
264	  int ret;
265	
266	  gpioinfo("Attaching the callback\n");
267	
268	  /* Make sure the interrupt is disabled */
269	
270	  esp32s3_gpioirqdisable(irq);
271	  ret = irq_attach(irq,
272	                   esp32s3gpio_interrupt,
273	                   &g_gpint[esp32s3gpint->esp32s3gpio.id]);
274	  if (ret < 0)
275	    {
276	      syslog(LOG_ERR, "ERROR: gpint_attach() failed: %d\n", ret);
277	      return ret;
278	    }
279	
280	  gpioinfo("Attach %p\n", callback);
281	  esp32s3gpint->callback = callback;
282	  return OK;
283	}
