285	/****************************************************************************
286	 * Name: gpint_enable
287	 ****************************************************************************/
288	
289	static int gpint_enable(struct gpio_dev_s *dev, bool enable)
290	{
291	  struct esp32s3gpint_dev_s *esp32s3gpint = (struct esp32s3gpint_dev_s *)dev;
292	  int irq = ESP32S3_PIN2IRQ(g_gpiointinputs[esp32s3gpint->esp32s3gpio.id]);
293	
294	  if (enable)
295	    {
296	      if (esp32s3gpint->callback != NULL)
297	        {
298	          gpioinfo("Enabling the interrupt\n");
299	
300	          /* Configure the interrupt for rising edge */
301	
302	          esp32s3_gpioirqenable(irq, RISING);
303	        }
304	    }
305	  else
306	    {
307	      gpioinfo("Disable the interrupt\n");
308	      esp32s3_gpioirqdisable(irq);
309	    }
310	
311	  return OK;
312	}
313	#endif
