316	 * Public Functions
317	 ****************************************************************************/
318	
319	/****************************************************************************
320	 * Name: esp32s3_gpio_init
321	 ****************************************************************************/
322	
323	int esp32s3_gpio_init(void)
324	{
325	  int pincount = 0;
326	  int i;
327	
328	#if BOARD_NGPIOOUT > 0
329	  for (i = 0; i < BOARD_NGPIOOUT; i++)
330	    {
331	      /* Setup and register the GPIO pin */
332	
333	      g_gpout[i].gpio.gp_pintype = GPIO_OUTPUT_PIN;
334	      g_gpout[i].gpio.gp_ops     = &gpout_ops;
335	      g_gpout[i].id              = i;
336	      gpio_pin_register(&g_gpout[i].gpio, pincount);
337	
338	      /* Configure the pins that will be used as output */
339	
340	      esp32s3_gpio_matrix_out(g_gpiooutputs[i], SIG_GPIO_OUT_IDX, 0, 0);
341	      esp32s3_configgpio(g_gpiooutputs[i], OUTPUT_FUNCTION_2 |
342	                         INPUT_FUNCTION_2);
343	      esp32s3_gpiowrite(g_gpiooutputs[i], 0);
344	
345	      pincount++;
346	    }
347	#endif
348	
349	#if BOARD_NGPIOIN > 0
350	  for (i = 0; i < BOARD_NGPIOIN; i++)
351	    {
352	      /* Setup and register the GPIO pin */
353	
354	      g_gpin[i].gpio.gp_pintype = GPIO_INPUT_PIN;
355	      g_gpin[i].gpio.gp_ops     = &gpin_ops;
356	      g_gpin[i].id              = i;
357	      gpio_pin_register(&g_gpin[i].gpio, pincount);
358	
359	      /* Configure the pins that will be used as INPUT */
360	
361	      esp32s3_configgpio(g_gpioinputs[i], INPUT_FUNCTION_2 | PULLUP);
362	
363	      pincount++;
364	    }
365	#endif
366	
367	#if BOARD_NGPIOINT > 0
368	  for (i = 0; i < BOARD_NGPIOINT; i++)
369	    {
370	      /* Setup and register the GPIO pin */
371	
372	      g_gpint[i].esp32s3gpio.gpio.gp_pintype = GPIO_INTERRUPT_PIN;
373	      g_gpint[i].esp32s3gpio.gpio.gp_ops     = &gpint_ops;
374	      g_gpint[i].esp32s3gpio.id              = i;
375	      gpio_pin_register(&g_gpint[i].esp32s3gpio.gpio, pincount);
376	
377	      /* Configure the pins that will be used as interrupt input */
378	
379	      esp32s3_configgpio(g_gpiointinputs[i], INPUT_FUNCTION_2 | PULLUP);
380	
381	      pincount++;
382	    }
383	#endif
384	
385	  return OK;
386	}
387	#endif /* CONFIG_DEV_GPIO && !CONFIG_GPIO_LOWER_HALF */
