/****************************************************************************
 * GPIO15 20MHz Clock Output
 *
 * Generates a precise 20MHz square wave on GPIO15 using the ESP32-S3 LEDC
 * peripheral. The LEDC (LED PWM Controller) can generate high-frequency
 * signals with hardware precision.
 *
 * Formula: freq = APB_CLK / (clk_div * 2^duty_res)
 *   APB_CLK  = 80 MHz
 *   clk_div  = 2.0
 *   duty_res = 1 (2 levels)
 *   freq     = 80 / (2.0 * 2) = 20 MHz
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdint.h>
#include <nuttx/arch.h>

#include "hardware/esp32s3_gpio.h"
#include "hardware/esp32s3_gpio_sigmap.h"
#include "hardware/esp32s3_ledc.h"
#include "periph_ctrl.h"
#include "esp32s3_gpio.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define GPIO_PIN_15           15

/* LEDC channel and timer to use (channel 0, timer 0) */

#define LEDC_CHANNEL          0
#define LEDC_TIMER            0

/* Clock divider: 2.0 in 18-bit fixed-point (8-bit integer + 8-bit fraction)
 * integer_part = 2, fractional_part = 0 -> (2 << 8) = 0x200
 */

#define LEDC_CLK_DIV_2_0      0x200

/* 1-bit duty resolution = 2 levels (high/low) */

#define LEDC_DUTY_RES_1BIT    1

/* APB clock source select for LEDC_CONF_REG */

#define LEDC_CLK_SRC_APB      1

/* GPIO matrix signal index for LEDC channel 0 output */

#define LEDC_SIG_OUT0         (LEDC_LS_SIG_OUT0_IDX + LEDC_CHANNEL)

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  printf("GPIO15 20MHz Clock Output\n");
  printf("Using LEDC peripheral: APB_CLK(80MHz) / (2.0 * 2^1) = 20MHz\n");

  /* Step 1: Enable LEDC peripheral clock */

  periph_module_enable(PERIPH_LEDC_MODULE);

  /* Step 2: Set LEDC global clock source to APB_CLK (80MHz) */

  putreg32(LEDC_CLK_SRC_APB, LEDC_CONF_REG);

  /* Step 3: Configure LEDC timer 0
   *   clk_div  = 2.0 (0x200 in 18-bit fixed-point)
   *   duty_res = 1   (1-bit resolution, 2 levels)
   *   Result: 80MHz / (2.0 * 2^1) = 20MHz
   */

  putreg32((LEDC_CLK_DIV_2_0 << LEDC_CLK_DIV_TIMER0_S) |
           (LEDC_DUTY_RES_1BIT << LEDC_TIMER0_DUTY_RES_S),
           LEDC_TIMER0_CONF_REG);

  /* Trigger timer parameter update */

  putreg32(getreg32(LEDC_TIMER0_CONF_REG) | LEDC_TIMER0_PARA_UP,
           LEDC_TIMER0_CONF_REG);

  /* Step 4: Configure LEDC channel 0 */

  /* Clear channel config registers */

  putreg32(0, LEDC_CH0_CONF0_REG);
  putreg32(0, LEDC_CH0_CONF1_REG);

  /* Select timer 0 for channel 0 */

  putreg32(LEDC_TIMER << LEDC_TIMER_SEL_CH0_S, LEDC_CH0_CONF0_REG);

  /* Set HPOINT = 0 (output goes high at counter value 0) */

  putreg32(0, LEDC_CH0_HPOINT_REG);

  /* Set DUTY = 1 (output goes low at counter value 1)
   * NuttX LEDC driver convention: actual duty value << 4
   */

  putreg32(1 << 4, LEDC_CH0_DUTY_REG);

  /* Enable signal output on channel 0 */

  putreg32(getreg32(LEDC_CH0_CONF0_REG) | LEDC_SIG_OUT_EN_CH0,
           LEDC_CH0_CONF0_REG);

  /* Start duty cycle application */

  putreg32(getreg32(LEDC_CH0_CONF1_REG) | LEDC_DUTY_START_CH0,
           LEDC_CH0_CONF1_REG);

  /* Trigger parameter update for channel 0 */

  putreg32(getreg32(LEDC_CH0_CONF0_REG) | LEDC_PARA_UP_CH0,
           LEDC_CH0_CONF0_REG);

  /* Wait for hardware to apply configuration */

  up_mdelay(1);

  /* Step 5: Configure GPIO15 as output and route LEDC signal to it */

  esp32s3_configgpio(GPIO_PIN_15, OUTPUT);
  esp32s3_gpio_matrix_out(GPIO_PIN_15, LEDC_SIG_OUT0, 0, 0);

  printf("20MHz signal is now running on GPIO15 (IO15).\n");
  printf("Signal will continue until board reset.\n");

  /* Keep running - the LEDC hardware generates the signal independently.
   * The CPU is not needed for signal generation once configured.
   */

  while (1)
    {
      sleep(1);
    }

  return 0;
}

