/****************************************************************************
 * GPIO15 20MHz Clock Output
 *
 * Generates a precise 20MHz square wave on GPIO15 using the ESP32-S3 LEDC
 * peripheral. The LEDC (LED PWM Controller) can generate high-frequency
 * signals with hardware precision.
 *
 * Formula: freq = APB_CLK / (clk_div * 2^duty_res)
 *   APB_CLK  = 80 MHz
 *   clk_div  = 2.0
 *   duty_res = 1 (2 levels)
 *   freq     = 80 / (2.0 * 2) = 20 MHz
 *
 * This replicates the same LEDC configuration used by the OV2640 camera
 * XCLK driver, but as a standalone user-space application.
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <nuttx/arch.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* ESP32-S3 register base addresses */

#define DR_REG_LEDC_BASE        0x60019000
#define DR_REG_GPIO_BASE        0x60004000

/* LEDC register offsets */

#define LEDC_CONF_REG           (DR_REG_LEDC_BASE + 0xd0)
#define LEDC_TIMER0_CONF_REG    (DR_REG_LEDC_BASE + 0xa0)
#define LEDC_CH0_CONF0_REG      (DR_REG_LEDC_BASE + 0x00)
#define LEDC_CH0_HPOINT_REG     (DR_REG_LEDC_BASE + 0x04)
#define LEDC_CH0_DUTY_REG       (DR_REG_LEDC_BASE + 0x08)
#define LEDC_CH0_CONF1_REG      (DR_REG_LEDC_BASE + 0x0c)

/* LEDC_CONF_REG fields */

#define LEDC_APB_CLK_SEL_S      0
#define LEDC_APB_CLK_SEL_V      0x1     /* APB_CLK = 80MHz */

/* LEDC_TIMER0_CONF_REG fields */

#define LEDC_TIMER0_DUTY_RES_S  0
#define LEDC_CLK_DIV_TIMER0_S   4
#define LEDC_TIMER0_PARA_UP     (1u << 25)

/* LEDC_CH0_CONF0_REG fields */

#define LEDC_TIMER_SEL_CH0_S    0
#define LEDC_SIG_OUT_EN_CH0     (1u << 2)
#define LEDC_PARA_UP_CH0        (1u << 4)

/* LEDC_CH0_CONF1_REG fields */

#define LEDC_DUTY_START_CH0     (1u << 31)

/* GPIO registers for pin 15 (pins 0-31 use OUT/ENABLE, not OUT1/ENABLE1) */

#define GPIO_OUT_W1TS_REG       (DR_REG_GPIO_BASE + 0x08)
#define GPIO_OUT_W1TC_REG       (DR_REG_GPIO_BASE + 0x0c)
#define GPIO_ENABLE_W1TS_REG    (DR_REG_GPIO_BASE + 0x24)

/* GPIO matrix */

#define GPIO_FUNC_OUT_SEL_CFG_REG(n) (DR_REG_GPIO_BASE + 0x530 + (n) * 4)

/* LEDC channel 0 output index in GPIO matrix */

#define LEDC_LS_SIG_OUT0_IDX   73

/* Clock divider: 2.0 in 18-bit fixed-point (8-bit integer + 8-bit fraction)
 * integer_part = 2, fractional_part = 0 -> (2 << 8) = 0x200
 */

#define LEDC_CLK_DIV_2_0       0x200

/* 1-bit duty resolution = 2 levels (high/low) */

#define LEDC_DUTY_RES_1BIT     1

/* GPIO pin to use */

#define GPIO_PIN               15

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  printf("GPIO15 20MHz Clock Output\n");
  printf("Using LEDC: APB_CLK(80MHz) / (2.0 * 2^1) = 20MHz\n");

  /* Step 1: Set LEDC global clock source to APB_CLK (80MHz) */

  putreg32(LEDC_APB_CLK_SEL_V << LEDC_APB_CLK_SEL_S, LEDC_CONF_REG);

  /* Step 2: Configure LEDC timer 0
   *   clk_div  = 2.0 (0x200 in 18-bit fixed-point: bit[21:4])
   *   duty_res = 1   (bit[3:0])
   *   Result: 80MHz / (2.0 * 2^1) = 20MHz
   */

  putreg32((LEDC_CLK_DIV_2_0 << LEDC_CLK_DIV_TIMER0_S) |
           (LEDC_DUTY_RES_1BIT << LEDC_TIMER0_DUTY_RES_S),
           LEDC_TIMER0_CONF_REG);

  /* Trigger timer parameter update */

  putreg32(getreg32(LEDC_TIMER0_CONF_REG) | LEDC_TIMER0_PARA_UP,
           LEDC_TIMER0_CONF_REG);

  /* Step 3: Configure LEDC channel 0 */

  /* Clear channel config registers */

  putreg32(0, LEDC_CH0_CONF0_REG);
  putreg32(0, LEDC_CH0_CONF1_REG);

  /* Select timer 0 for channel 0 */

  putreg32(0 << LEDC_TIMER_SEL_CH0_S, LEDC_CH0_CONF0_REG);

  /* Set HPOINT = 0 (output goes high at counter value 0) */

  putreg32(0, LEDC_CH0_HPOINT_REG);

  /* Set DUTY = 1 (output goes low at counter value 1)
   * NuttX LEDC driver convention: actual duty value << 4
   */

  putreg32(1 << 4, LEDC_CH0_DUTY_REG);

  /* Enable signal output on channel 0 */

  putreg32(getreg32(LEDC_CH0_CONF0_REG) | LEDC_SIG_OUT_EN_CH0,
           LEDC_CH0_CONF0_REG);

  /* Start duty cycle application */

  putreg32(getreg32(LEDC_CH0_CONF1_REG) | LEDC_DUTY_START_CH0,
           LEDC_CH0_CONF1_REG);

  /* Trigger parameter update for channel 0 */

  putreg32(getreg32(LEDC_CH0_CONF0_REG) | LEDC_PARA_UP_CH0,
           LEDC_CH0_CONF0_REG);

  /* Wait for hardware to apply configuration */

  up_mdelay(1);

  /* Step 4: Configure GPIO15 as output
   * Enable output for pin 15 (set bit 15 in ENABLE_W1TS)
   */

  putreg32(1u << GPIO_PIN, GPIO_ENABLE_W1TS_REG);

  /* Route LEDC channel 0 output to GPIO15 via GPIO matrix
