/****************************************************************************
 * GPIO15 20MHz Clock Output
 *
 * Generates a precise 20MHz square wave on GPIO15 using the ESP32-S3 LEDC
 * peripheral. The LEDC (LED PWM Controller) can generate high-frequency
 * signals with hardware precision.
 *
 * Formula: freq = APB_CLK / (clk_div * 2^duty_res)
 *   APB_CLK  = 80 MHz
 *   clk_div  = 2.0
 *   duty_res = 1 (2 levels)
 *   freq     = 80 / (2.0 * 2) = 20 MHz
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* ESP32-S3 peripheral base addresses (physical) */

#define DR_REG_LEDC_BASE        0x60019000
#define DR_REG_GPIO_BASE        0x60004000

/* We need to map 4KB pages that contain our registers.
 * LEDC registers: 0x60019000 - 0x600190fc  (page 0x60019000)
 * GPIO registers: 0x60004000 - 0x60004530+ (page 0x60004000)
 */

#define LEDC_PAGE_BASE          (DR_REG_LEDC_BASE & ~0xfff)
#define GPIO_PAGE_BASE          (DR_REG_GPIO_BASE & ~0xfff)
#define PAGE_SIZE               0x1000

/* LEDC register offsets from DR_REG_LEDC_BASE */

#define LEDC_CONF_REG           0xd0
#define LEDC_TIMER0_CONF_REG    0xa0
#define LEDC_CH0_CONF0_REG      0x00
#define LEDC_CH0_HPOINT_REG     0x04
#define LEDC_CH0_DUTY_REG       0x08
#define LEDC_CH0_CONF1_REG      0x0c

/* LEDC_CONF_REG fields */

#define LEDC_APB_CLK_SEL_S      0
#define LEDC_APB_CLK_SEL_V      0x1     /* APB_CLK = 80MHz */

/* LEDC_TIMER0_CONF_REG fields */

#define LEDC_TIMER0_DUTY_RES_S  0
#define LEDC_CLK_DIV_TIMER0_S   4
#define LEDC_TIMER0_PARA_UP     (1u << 25)

/* LEDC_CH0_CONF0_REG fields */

#define LEDC_TIMER_SEL_CH0_S    0
#define LEDC_SIG_OUT_EN_CH0     (1u << 2)
#define LEDC_PARA_UP_CH0        (1u << 4)

/* LEDC_CH0_CONF1_REG fields */

#define LEDC_DUTY_START_CH0     (1u << 31)

/* GPIO registers (offset from DR_REG_GPIO_BASE) */

#define GPIO_ENABLE_W1TS_REG    0x24

/* GPIO matrix: function-out-select for pin N */

#define GPIO_FUNC_OUT_SEL_CFG_REG(n) (0x530 + (n) * 4)

/* LEDC channel 0 output index in GPIO matrix */

#define LEDC_LS_SIG_OUT0_IDX   73

/* Clock divider: 2.0 in 18-bit fixed-point (8-bit integer + 8-bit fraction)
 * integer_part = 2, fractional_part = 0 -> (2 << 8) = 0x200
 */

#define LEDC_CLK_DIV_2_0       0x200

/* 1-bit duty resolution = 2 levels (high/low) */

#define LEDC_DUTY_RES_1BIT     1

/* GPIO pin to use */

#define GPIO_PIN               15

/****************************************************************************
 * Private Helpers
 ****************************************************************************/

static inline void reg_write(volatile uint32_t *base, uint32_t off,
                             uint32_t val)
{
  *(volatile uint32_t *)((uintptr_t)base + off) = val;
}

static inline uint32_t reg_read(volatile uint32_t *base, uint32_t off)
{
  return *(volatile uint32_t *)((uintptr_t)base + off);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  volatile uint32_t *ledc;
  volatile uint32_t *gpio;
  int fd;

  printf("GPIO15 20MHz Clock Output\n");
  printf("Using LEDC: APB_CLK(80MHz) / (2.0 * 2^1) = 20MHz\n");

  /* Open /dev/mem for physical memory access */

  fd = open("/dev/mem", O_RDWR | O_SYNC);
  if (fd < 0)
    {
      printf("ERROR: Failed to open /dev/mem (need root/caps)\n");
      return -1;
    }

  /* Map LEDC register page */

  ledc = (volatile uint32_t *)mmap(NULL, PAGE_SIZE, PROT_READ | PROT_WRITE,
                                   MAP_SHARED, fd, LEDC_PAGE_BASE);
  if (ledc == MAP_FAILED)
    {
      printf("ERROR: Failed to mmap LEDC registers\n");
      close(fd);
      return -1;
    }

  /* Map GPIO register page */

  gpio = (volatile uint32_t *)mmap(NULL, PAGE_SIZE, PROT_READ | PROT_WRITE,
                                   MAP_SHARED, fd, GPIO_PAGE_BASE);
  if (gpio == MAP_FAILED)
    {
      printf("ERROR: Failed to mmap GPIO registers\n");
      munmap((void *)ledc, PAGE_SIZE);
      close(fd);
      return -1;
    }

  close(fd);

  /* Calculate register offsets within mapped pages */

  uint32_t ledc_off = DR_REG_LEDC_BASE - LEDC_PAGE_BASE;
  uint32_t gpio_off = DR_REG_GPIO_BASE - GPIO_PAGE_BASE;

  /* Step 1: Set LEDC global clock source to APB_CLK (80MHz) */

  reg_write(ledc, ledc_off + LEDC_CONF_REG,
            LEDC_APB_CLK_SEL_V << LEDC_APB_CLK_SEL_S);

  /* Step 2: Configure LEDC timer 0
   *   clk_div  = 2.0 (0x200 in 18-bit fixed-point: bit[21:4])
   *   duty_res = 1   (bit[3:0])
   *   Result: 80MHz / (2.0 * 2^1) = 20MHz
   */

  reg_write(ledc, ledc_off + LEDC_TIMER0_CONF_REG,
            (LEDC_CLK_DIV_2_0 << LEDC_CLK_DIV_TIMER0_S) |
            (LEDC_DUTY_RES_1BIT << LEDC_TIMER0_DUTY_RES_S));

  /* Trigger timer parameter update */

  reg_write(ledc, ledc_off + LEDC_TIMER0_CONF_REG,
            reg_read(ledc, ledc_off + LEDC_TIMER0_CONF_REG) |
            LEDC_TIMER0_PARA_UP);

  /* Step 3: Configure LEDC channel 0 */

  /* Clear channel config registers */

  reg_write(ledc, ledc_off + LEDC_CH0_CONF0_REG, 0);
  reg_write(ledc, ledc_off + LEDC_CH0_CONF1_REG, 0);

  /* Select timer 0 for channel 0 */

  reg_write(ledc, ledc_off + LEDC_CH0_CONF0_REG,
            0 << LEDC_TIMER_SEL_CH0_S);

  /* Set HPOINT = 0 (output goes high at counter value 0) */

  reg_write(ledc, ledc_off + LEDC_CH0_HPOINT_REG, 0);

  /* Set DUTY = 1 (output goes low at counter value 1)
   * NuttX LEDC driver convention: actual duty value << 4
   */

  reg_write(ledc, ledc_off + LEDC_CH0_DUTY_REG, 1 << 4);

  /* Enable signal output on channel 0 */

  reg_write(ledc, ledc_off + LEDC_CH0_CONF0_REG,
            reg_read(ledc, ledc_off + LEDC_CH0_CONF0_REG) |
            LEDC_SIG_OUT_EN_CH0);

  /* Start duty cycle application */

  reg_write(ledc, ledc_off + LEDC_CH0_CONF1_REG,
            reg_read(ledc, ledc_off + LEDC_CH0_CONF1_REG) |
            LEDC_DUTY_START_CH0);

  /* Trigger parameter update for channel 0 */

  reg_write(ledc, ledc_off + LEDC_CH0_CONF0_REG,
            reg_read(ledc, ledc_off + LEDC_CH0_CONF0_REG) |
            LEDC_PARA_UP_CH0);

  /* Wait for hardware to apply configuration */

  usleep(1000);

  /* Step 4: Configure GPIO15 as output
   * Enable output for pin 15 (set bit 15 in ENABLE_W1TS)
   */

  reg_write(gpio, gpio_off + GPIO_ENABLE_W1TS_REG, 1u << GPIO_PIN);

  /* Route LEDC channel 0 output to GPIO15 via GPIO matrix
   * GPIO_FUNC_OUT_SEL_CFG_REG(15) = LEDC_LS_SIG_OUT0_IDX (73)
   */

  reg_write(gpio, gpio_off + GPIO_FUNC_OUT_SEL_CFG_REG(GPIO_PIN),
            LEDC_LS_SIG_OUT0_IDX);

  printf("20MHz signal is now running on GPIO%d (IO%d).\n",
         GPIO_PIN, GPIO_PIN);
  printf("Signal will continue until board reset.\n");

  /* The LEDC hardware generates the signal independently of the CPU.
   * Keep the process alive so NSH doesn't reclaim resources.
   */

  while (1)
    {
      sleep(1);
    }

  return 0;
}

