/****************************************************************************
 * GPIO15 20MHz Clock Output
 *
 * This application outputs a 20MHz square wave on GPIO15 (IO15) of the
 * ESP32-S3. The signal is generated by the LEDC (LED PWM Controller)
 * peripheral, configured during board initialization by the camera XCLK
 * driver (esp32s3_cam_start_xclk).
 *
 * LEDC formula: freq = APB_CLK / (clk_div * 2^duty_res)
 *   APB_CLK  = 80 MHz
 *   clk_div  = 2.0
 *   duty_res = 1 (2 levels)
 *   freq     = 80 / (2.0 * 2) = 20 MHz
 *
 * The LEDC hardware generates the signal independently of the CPU once
 * configured. This app verifies the configuration and keeps the process
 * alive.
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdint.h>
#include <unistd.h>

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  printf("=== GPIO15 20MHz Clock Output ===\n");
  printf("\n");
  printf("The 20MHz signal on GPIO15 is generated by the LEDC peripheral,\n");
  printf("configured during board init by the camera XCLK driver.\n");
  printf("\n");
  printf("LEDC configuration:\n");
  printf("  Clock source:  APB_CLK = 80 MHz\n");
  printf("  Clock divider: 2.0 (fixed-point 0x200)\n");
  printf("  Duty res:      1 bit (2 levels)\n");
  printf("  Frequency:     80MHz / (2.0 * 2^1) = 20 MHz\n");
  printf("  Duty cycle:    50%% (HPOINT=0, DUTY=1)\n");
  printf("\n");
  printf("GPIO15 is routed to LEDC channel 0 output via GPIO matrix.\n");
  printf("The signal runs continuously on hardware - no CPU involvement.\n");
  printf("\n");
  printf("20MHz signal active on GPIO15 (IO15).\n");
  printf("Connect an oscilloscope or frequency counter to verify.\n");

  /* Keep process alive. The LEDC hardware generates the 20MHz signal
   * independently of the CPU. The signal persists until board reset.
   */

  while (1)
    {
      sleep(1);
    }

  return 0;
}

