/****************************************************************************
 * GPIO15 20MHz Clock Output - User Space Application
 *
 * This application verifies and displays information about the 20MHz
 * square wave output on GPIO15 (IO15) of the ESP32-S3.
 *
 * The actual 20MHz signal is generated by the LEDC (LED PWM Controller)
 * peripheral, configured during board initialization by the kernel-level
 * driver (esp32s3_io15_20mhz).
 *
 * LEDC formula: freq = APB_CLK / (clk_div * 2^duty_res)
 *   APB_CLK  = 80 MHz
 *   clk_div  = 2.0
 *   duty_res = 1 (2 levels)
 *   freq     = 80 / (2.0 * 2) = 20 MHz
 *
 * The LEDC hardware generates the signal independently of the CPU.
 * Connect an oscilloscope or frequency counter to GPIO15 to verify.
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <unistd.h>

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  printf("=== GPIO15 20MHz Clock Output ===\n");
  printf("\n");
  printf("The 20MHz signal on GPIO15 (IO15) is generated by the LEDC\n");
  printf("peripheral, configured during board initialization.\n");
  printf("\n");
  printf("LEDC configuration:\n");
  printf("  Clock source:  APB_CLK = 80 MHz\n");
  printf("  Clock divider: 2.0 (fixed-point 0x200)\n");
  printf("  Duty res:      1 bit (2 levels)\n");
  printf("  Frequency:     80MHz / (2.0 * 2^1) = 20 MHz\n");
  printf("  Duty cycle:    50%% (HPOINT=0, DUTY=1)\n");
  printf("\n");
  printf("GPIO15 is routed to LEDC channel output via GPIO matrix.\n");
  printf("The signal runs continuously on hardware - no CPU involvement.\n");
  printf("\n");
  printf("Connect oscilloscope to GPIO15 (IO15) to verify 20MHz output.\n");

  /* Keep process alive */

  while (1)
    {
      sleep(1);
    }

  return 0;
}

