/****************************************************************************
 * Name: esp32s3_io15_20mhz
 *
 * Description:
 *   Generate a 20MHz square wave on GPIO15 (IO15) using the LEDC peripheral.
 *
 *   LEDC timer formula: freq = clk_src / (clk_div * 2^duty_res)
 *   Using APB_CLK = 80 MHz, duty_res = 1 (2 levels), clk_div = 2:
 *     freq = 80 / (2 * 2) = 20 MHz
 *
 *   CLK_DIV_TIMER0 is 18-bit fixed-point: 8-bit integer + 8-bit fraction.
 *   div = 2.0 -> integer_part = 2, fractional_part = 0 -> (2 << 8) = 0x200
 *
 *   HPOINT = 0, DUTY = 1 -> 50% duty cycle (high 1 tick, low 1 tick)
 *
 *   The LEDC hardware generates the signal independently of the CPU once
 *   configured. Signal persists until board reset.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <syslog.h>
#include <nuttx/arch.h>

#include "esp32s3_gpio.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* ESP32-S3 register base addresses */

#define DR_REG_LEDC_BASE        0x60019000

/* LEDC register addresses */

#define LEDC_CONF_REG           (DR_REG_LEDC_BASE + 0xd0)
#define LEDC_TIMER0_CONF_REG    (DR_REG_LEDC_BASE + 0xa0)
#define LEDC_CH1_CONF0_REG      (DR_REG_LEDC_BASE + 0x14)
#define LEDC_CH1_HPOINT_REG     (DR_REG_LEDC_BASE + 0x18)
#define LEDC_CH1_DUTY_REG       (DR_REG_LEDC_BASE + 0x1c)
#define LEDC_CH1_CONF1_REG      (DR_REG_LEDC_BASE + 0x20)

/* LEDC_CONF_REG fields */

#define LEDC_APB_CLK_SEL_S      0

/* LEDC_TIMER0_CONF_REG fields */

#define LEDC_TIMER0_DUTY_RES_S  0
#define LEDC_CLK_DIV_TIMER0_S   4
#define LEDC_TIMER0_PARA_UP     (1u << 25)

/* LEDC_CHx_CONF0_REG fields (same bit positions for all channels) */

#define LEDC_TIMER_SEL_S        0
#define LEDC_SIG_OUT_EN         (1u << 2)
#define LEDC_PARA_UP            (1u << 4)

/* LEDC_CHx_CONF1_REG fields */

#define LEDC_DUTY_START         (1u << 31)

/* GPIO matrix signal index for LEDC channel outputs */

#define LEDC_LS_SIG_OUT0_IDX   73

/* Clock divider: 2.0 in 18-bit fixed-point (8-bit integer + 8-bit fraction)
 * integer_part = 2, fractional_part = 0 -> (2 << 8) = 0x200
 */

#define LEDC_CLK_DIV_2_0       0x200

/* GPIO pin for 20MHz output */

#define IO15_20MHZ_PIN          15

/* LEDC timer and channel */

#define IO15_LEDC_TIMER         0
#define IO15_LEDC_CHANNEL       1

/* APB clock source for LEDC */

#define LEDC_CLK_RES_APB        1

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int esp32s3_io15_20mhz(void)
{
  /* Enable LEDC peripheral clock */

  periph_module_enable(PERIPH_LEDC_MODULE);

  /* Step 0: Set LEDC clock source to APB_CLK (80MHz) */

  putreg32(LEDC_CLK_RES_APB, LEDC_CONF_REG);

  /* Step 1: Configure LEDC timer 0
   * freq = APB_CLK(80MHz) / (clk_div * 2^duty_res)
   *      = 80MHz / (2.0 * 2^1) = 20MHz
   */

  putreg32((LEDC_CLK_DIV_2_0 << LEDC_CLK_DIV_TIMER0_S) |
           (1 << LEDC_TIMER0_DUTY_RES_S),
           LEDC_TIMER0_CONF_REG);

  /* Apply timer configuration */

  putreg32(getreg32(LEDC_TIMER0_CONF_REG) | LEDC_TIMER0_PARA_UP,
           LEDC_TIMER0_CONF_REG);

  /* Step 2: Clear channel 1 registers */

  putreg32(0, LEDC_CH1_CONF0_REG);
  putreg32(0, LEDC_CH1_CONF1_REG);

  /* Step 3: Select timer 0 for channel 1 */

  putreg32(IO15_LEDC_TIMER << LEDC_TIMER_SEL_S, LEDC_CH1_CONF0_REG);

  /* Step 4: Set HPOINT = 0 */

  putreg32(0, LEDC_CH1_HPOINT_REG);

  /* Step 5: Set DUTY = 1 (50% duty at 1-bit resolution)
   * NuttX LEDC driver convention: actual duty value << 4
   */

  putreg32(1 << 4, LEDC_CH1_DUTY_REG);

  /* Step 6: Enable signal output */

  putreg32(getreg32(LEDC_CH1_CONF0_REG) | LEDC_SIG_OUT_EN,
           LEDC_CH1_CONF0_REG);

  /* Step 7: Start duty cycle */

  putreg32(getreg32(LEDC_CH1_CONF1_REG) | LEDC_DUTY_START,
           LEDC_CH1_CONF1_REG);

  /* Step 8: Trigger parameter update */

  putreg32(getreg32(LEDC_CH1_CONF0_REG) | LEDC_PARA_UP,
           LEDC_CH1_CONF0_REG);

  /* Wait for hardware to apply */

  up_mdelay(1);

  /* Step 9: Connect LEDC channel 1 output to GPIO15 via GPIO matrix */

  esp32s3_configgpio(IO15_20MHZ_PIN, OUTPUT);
  esp32s3_gpio_matrix_out(IO15_20MHZ_PIN,
                           LEDC_LS_SIG_OUT0_IDX + IO15_LEDC_CHANNEL,
                           0, 0);

  syslog(LOG_INFO, "io15_20mhz: 20MHz signal started on GPIO%d "
         "(LEDC ch%d, timer%d)\n",
         IO15_20MHZ_PIN, IO15_LEDC_CHANNEL, IO15_LEDC_TIMER);

  return OK;
}

