/****************************************************************************
 * Contest 2026 team 026 - OV2640 Camera Real-time Display
 *
 * Captures frames from OV2640 camera via V4L2 interface and displays
 * them on the ST7789 LCD in real-time.
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/mman.h>

#include <nuttx/video/video.h>
#include <nuttx/video/fb.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define CAMERA_DEV_PATH   "/dev/video"
#define FB_DEV_PATH       "/dev/fb0"
#define FRAME_WIDTH       320
#define FRAME_HEIGHT      240
#define FRAME_SIZE        (FRAME_WIDTH * FRAME_HEIGHT * 2)  /* RGB565 */
#define LCD_WIDTH         240
#define LCD_HEIGHT        240
#define CROP_X            ((FRAME_WIDTH - LCD_WIDTH) / 2)   /* 40 */
#define BUF_COUNT         3

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: display_frame
 *
 * Description:
 *   Display a 320x240 RGB565 frame on the 240x240 LCD by center cropping.
 ****************************************************************************/

static int display_frame(int fb_fd, const uint8_t *frame,
                         struct fb_videoinfo_s *vinfo,
                         struct fb_planeinfo_s *pinfo)
{
  uint8_t *fbmem = (uint8_t *)pinfo->fbmem;
  int y;

  if (fbmem == NULL)
    {
      return -ENOMEM;
    }

  /* Center crop: take middle 240 columns from 320-wide frame */

  for (y = 0; y < LCD_HEIGHT; y++)
    {
      const uint16_t *src = (const uint16_t *)(frame +
                              (y * FRAME_WIDTH + CROP_X) * 2);
      uint16_t *dst = (uint16_t *)(fbmem + y * pinfo->stride);
      memcpy(dst, src, LCD_WIDTH * 2);
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  int cam_fd;
  int fb_fd;
  int ret;
  struct v4l2_format fmt;
  struct v4l2_requestbuffers req;
  struct v4l2_buffer buf;
  enum v4l2_buf_type type;
  struct fb_videoinfo_s vinfo;
  struct fb_planeinfo_s pinfo;
  struct timeval start_tv;
  struct timeval now_tv;
  int frame_count = 0;
  uint8_t *frame_data;

  printf("OV2640 Camera -> LCD Real-time Display\n");

  /* Open framebuffer device */

  fb_fd = open(FB_DEV_PATH, O_RDWR);
  if (fb_fd < 0)
    {
      printf("ERROR: Failed to open %s: %d\n", FB_DEV_PATH, errno);
      return -errno;
    }

  /* Get framebuffer info */

  ret = ioctl(fb_fd, FBIOGET_VIDEOINFO, (unsigned long)&vinfo);
  if (ret < 0)
    {
      printf("ERROR: FBIOGET_VIDEOINFO failed: %d\n", errno);
      close(fb_fd);
      return ret;
    }

  ret = ioctl(fb_fd, FBIOGET_PLANEINFO, (unsigned long)&pinfo);
  if (ret < 0)
    {
      printf("ERROR: FBIOGET_PLANEINFO failed: %d\n", errno);
      close(fb_fd);
      return ret;
    }

  printf("LCD: %dx%d, stride=%d\n", vinfo.xres, vinfo.yres, pinfo.stride);

  /* Open camera device */

  cam_fd = open(CAMERA_DEV_PATH, O_RDONLY);
  if (cam_fd < 0)
    {
      printf("ERROR: Failed to open %s: %d\n", CAMERA_DEV_PATH, errno);
      close(fb_fd);
      return -errno;
    }

  /* Set camera format: QVGA RGB565 */

  memset(&fmt, 0, sizeof(fmt));
  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width = FRAME_WIDTH;
  fmt.fmt.pix.height = FRAME_HEIGHT;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;

  ret = ioctl(cam_fd, VIDIOC_S_FMT, (unsigned long)&fmt);
  if (ret < 0)
    {
      printf("ERROR: VIDIOC_S_FMT failed: %d\n", errno);
      goto err_close;
    }

  /* Request buffers */

  memset(&req, 0, sizeof(req));
  req.count = BUF_COUNT;
  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  req.memory = V4L2_MEMORY_MMAP;

  ret = ioctl(cam_fd, VIDIOC_REQBUFS, (unsigned long)&req);
  if (ret < 0)
    {
      printf("ERROR: VIDIOC_REQBUFS failed: %d\n", errno);
      goto err_close;
    }

  /* Queue all buffers */

  for (int i = 0; i < BUF_COUNT; i++)
    {
      memset(&buf, 0, sizeof(buf));
      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_MMAP;
      buf.index = i;

      ret = ioctl(cam_fd, VIDIOC_QBUF, (unsigned long)&buf);
      if (ret < 0)
        {
          printf("ERROR: VIDIOC_QBUF[%d] failed: %d\n", i, errno);
          goto err_close;
        }
    }

  /* Start streaming */

  type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  ret = ioctl(cam_fd, VIDIOC_STREAMON, (unsigned long)&type);
  if (ret < 0)
    {
      printf("ERROR: VIDIOC_STREAMON failed: %d\n", errno);
      goto err_close;
    }

  printf("Camera streaming started. Press Ctrl+C to stop.\n");
  gettimeofday(&start_tv, NULL);

  /* Main capture loop */

  while (1)
    {
      /* Dequeue a frame */

      memset(&buf, 0, sizeof(buf));
      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_MMAP;

      ret = ioctl(cam_fd, VIDIOC_DQBUF, (unsigned long)&buf);
      if (ret < 0)
        {
          printf("ERROR: VIDIOC_DQBUF failed: %d\n", errno);
          break;
        }

      /* Map frame data */

      frame_data = (uint8_t *)mmap(NULL, buf.length, PROT_READ,
                                    MAP_SHARED, cam_fd, buf.m.offset);
      if (frame_data == MAP_FAILED)
        {
          printf("ERROR: mmap failed: %d\n", errno);
          break;
        }

      /* Display frame on LCD */

      display_frame(fb_fd, frame_data, &vinfo, &pinfo);

      /* Unmap */

      munmap(frame_data, buf.length);

      /* Requeue buffer */

      ret = ioctl(cam_fd, VIDIOC_QBUF, (unsigned long)&buf);
      if (ret < 0)
        {
          printf("ERROR: VIDIOC_QBUF failed: %d\n", errno);
          break;
        }

      /* Print FPS every second */

      frame_count++;
      gettimeofday(&now_tv, NULL);
      long elapsed_ms = (now_tv.tv_sec - start_tv.tv_sec) * 1000 +
                        (now_tv.tv_usec - start_tv.tv_usec) / 1000;

      if (elapsed_ms >= 1000)
        {
          printf("FPS: %ld\n", frame_count * 1000 / elapsed_ms);
          frame_count = 0;
          start_tv = now_tv;
        }
    }

  /* Cleanup */

  ioctl(cam_fd, VIDIOC_STREAMOFF, (unsigned long)&type);

err_close:
  close(cam_fd);
  close(fb_fd);
  return 0;
}
